import { describe, expect, it } from 'vitest';
import { MiiCharacterData, MII_WORD_COUNT } from './MiiCharacterData';
import { DEFAULT_MII_HEX } from '../generated/default-character';

// Independent fixture copied from the original AS3 literal, not generated by the codec.
const ORIGINAL = '000000640065006600610075006c00740042006f0079404080807f5fc242899800044240318028a2088c08401448b88d008a008a25040000000000000000000000000000000000000000';

function verifyUntouched(before: Uint8Array, after: Uint8Array): void {
  expect(after.slice(0, 2)).toEqual(before.slice(0, 2));
  expect(after.slice(22)).toEqual(before.slice(22));
}

describe('original default', () => {
  it('loads the exact source fixture and decodes defaultBoy', () => {
    expect(DEFAULT_MII_HEX).toBe(ORIGINAL);
    const mii = MiiCharacterData.fromHex(DEFAULT_MII_HEX);
    expect(mii.name).toBe('defaultBoy');
    expect(mii.toHex()).toBe(ORIGINAL);
    expect(mii.toBytes()).toHaveLength(74);
    expect(mii.toWords()).toHaveLength(MII_WORD_COUNT);
    expect(mii.toWords()[1]).toBe(0x0064);
    expect(mii.toWords()[11]).toBe(0x4040);
  });
  it('does not change a byte when assigning the existing name', () => {
    const mii = MiiCharacterData.fromHex(ORIGINAL);
    mii.name = mii.name;
    expect(mii.toHex()).toBe(ORIGINAL);
  });
});

describe('name writes preserve every other byte', () => {
  it.each([
    ['', '0000000000000000000000000000000000000000', ''],
    ['A', '0041000000000000000000000000000000000000', 'A'],
    ['1234567890', '0031003200330034003500360037003800390030', '1234567890'],
    ['1234567890extra', '0031003200330034003500360037003800390030', '1234567890'],
    ['Zoë水', '005a006f00eb6c34000000000000000000000000', 'Zoë水'],
    ['😀', 'd83dde0000000000000000000000000000000000', '😀'],
    ['123456789😀', '003100320033003400350036003700380039d83d', '123456789\ud83d'],
    ['A\u0000B', '0041000000420000000000000000000000000000', 'AB'],
  ])('encodes %j with exact expected words', (input, expected, decoded) => {
    const mii = MiiCharacterData.fromHex(ORIGINAL);
    const before = mii.toBytes();
    mii.name = input;
    expect(mii.toHex().slice(4, 44)).toBe(expected);
    expect(mii.name).toBe(decoded);
    expect(mii.toHex()).toHaveLength(148);
    verifyUntouched(before, mii.toBytes());
  });
  it('clears the tail when a longer name is shortened', () => {
    const mii = MiiCharacterData.fromHex(ORIGINAL);
    mii.name = '1234567890';
    mii.name = 'B';
    expect(mii.toHex().slice(4, 44)).toBe('0042' + '0000'.repeat(9));
  });
  it('preserves arbitrary unknown/reserved bytes for every name length', () => {
    for (let seed = 0; seed < 256; seed += 1) {
      const bytes = Uint8Array.from({ length: 74 }, (_, index) => (seed * 31 + index * 97) & 255);
      const mii = MiiCharacterData.fromBytes(bytes);
      expect(mii.toBytes()).toEqual(bytes);
      mii.name = '水'.repeat(seed % 14);
      verifyUntouched(bytes, mii.toBytes());
    }
  });
});

describe('binary structure and API boundaries', () => {
  it('uses big endian regardless of host endian, including 0xffff', () => {
    const bytes = Uint8Array.from({ length: 74 }, (_, index) => index);
    const mii = MiiCharacterData.fromBytes(bytes);
    expect(mii.toWords()[0]).toBe(0x0001);
    expect(mii.toWords()[36]).toBe(0x4849);
    expect(mii.toBytes()).toEqual(bytes);
    expect(MiiCharacterData.fromHex('ff'.repeat(74)).toWords()[0]).toBe(65535);
  });
  it('handles offset byte views without reading bytes outside the view', () => {
    const backing = new Uint8Array(80).fill(0xff);
    backing.set(Uint8Array.from({ length: 74 }, (_, index) => index), 3);
    const view = backing.subarray(3, 77);
    expect(MiiCharacterData.fromBytes(view).toBytes()).toEqual(view);
  });
  it('owns its data and returns defensive copies', () => {
    const bytes = MiiCharacterData.fromHex(ORIGINAL).toBytes();
    const mii = MiiCharacterData.fromBytes(bytes);
    bytes.fill(255);
    mii.toBytes().fill(0);
    mii.toWords().fill(0);
    expect(mii.toHex()).toBe(ORIGINAL);
  });
  it.each([0, 73, 75])('rejects a %i-byte buffer', (length) => {
    expect(() => MiiCharacterData.fromBytes(new Uint8Array(length))).toThrow(RangeError);
  });
  it.each(['', '0'.repeat(147), '0'.repeat(149), 'g'.repeat(148), ' '.repeat(148), ORIGINAL + '\n'])('rejects invalid internal fixture hex %j', (hex) => {
    expect(() => MiiCharacterData.fromHex(hex)).toThrow(TypeError);
  });
  it('accepts uppercase fixture hex and serializes lowercase', () => {
    expect(MiiCharacterData.fromHex(ORIGINAL.toUpperCase()).toHex()).toBe(ORIGINAL);
  });
});
